    "type": "function",
    "function": {
      "name": "lookup_customer",
      "description": "Return the customer's profile (name, tier).",
      "parameters": {
        "type": "object",
        "properties": {
          "customer_id": {
            "type": "string",
            "description": "Customer id, e.g. C-1049."
          }
